#!/bin/sh
# Entrypoint of the send-only mail relay (service "mail" in
# docker/docker-compose.selfhost.yml, image foxcpp/maddy). Checks the
# settings, turns the relay password into the hash maddy.conf expects and
# starts maddy. The DKIM key is generated by maddy itself on the first start
# and stays in the mail-data volume.
set -eu

fail() {
  echo "mail: $*" >&2
  exit 1
}

[ -n "${MAIL_DOMAIN:-}" ] || fail "MAIL_DOMAIN is not set (the domain of EMAIL_FROM)"
[ -n "${MAIL_HOSTNAME:-}" ] || fail "MAIL_HOSTNAME is not set (the name the PTR record of the server IP points to)"
if [ -z "${SMTP_USER:-}" ] || [ -z "${SMTP_PASSWORD:-}" ]; then
  fail "SMTP_USER and SMTP_PASSWORD must be set — the app's login for this relay (.env.selfhost)"
fi
export MAIL_DKIM_SELECTOR="${MAIL_DKIM_SELECTOR:-cg}"

# maddy reads the password from stdin when it is not a terminal (its prompt
# and terminal warnings go to stderr)
MAIL_RELAY_PASSWORD_HASH="$(printf '%s\n' "$SMTP_PASSWORD" | /bin/maddy hash 2>/dev/null)" \
  || fail "could not hash the relay password"
export MAIL_RELAY_PASSWORD_HASH
# SMTP_PASSWORD stays set: maddy.conf also uses the login in clear to deliver
# bounce reports to the app's receiver

key="/data/dkim_keys/${MAIL_DOMAIN}_${MAIL_DKIM_SELECTOR}.key"
if [ ! -f "$key" ]; then
  echo "mail: no DKIM key for ${MAIL_DOMAIN} (selector ${MAIL_DKIM_SELECTOR}) yet — maddy generates it now;"
  echo "mail: run ./selfhost/selfhost.sh mail-dns for the DNS records to publish"
fi

exec /bin/maddy -config /etc/maddy/maddy.conf run
